{
  "case_id": "C04",
  "audience": "Coaches and sports-science students",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "Iron deficiency without anaemia shows up in fifteen to thirty-five percent of adolescent endurance athletes, depending on the ferritin cut-off you use.",
      "on_screen": "Title card: Iron deficiency without anaemia. Stat: 15-35% of adolescent endurance athletes.",
      "claim_refs": ["SYN-C04:background"]
    },
    {
      "beat": "Why every other day",
      "narration": "A daily iron dose pushes hepcidin up for twenty-four hours or more, which blunts absorption of the next dose. Alternate-day dosing waits for hepcidin to fall first. In adolescents, that evidence was thin.",
      "on_screen": "Simple curve: hepcidin rises after a dose, then falls. Daily dosing versus alternate-day dosing arrows.",
      "claim_refs": ["SYN-C04:background", "SYN-C04:methods:rationale"]
    },
    {
      "beat": "The trial",
      "narration": "So this double-blind randomised trial took two hundred fourteen athletes, aged fifteen to eighteen, all with ferritin below thirty micrograms per litre. Sixty milligrams of elemental iron every other day, or matched placebo, for twelve weeks. Adherence was ninety-one percent.",
      "on_screen": "Trial card: n=214, ages 15-18, ferritin <30 ug/L, 60 mg elemental iron alternate days vs placebo, 12 weeks, adherence 91%.",
      "claim_refs": ["SYN-C04:design", "SYN-C04:results:dose", "SYN-C04:methods:adherence"]
    },
    {
      "beat": "What changed",
      "narration": "Ferritin rose eighteen point four micrograms per litre on iron, versus two point one on placebo. That is a between-group difference of sixteen point three, confidence interval twelve point nine to nineteen point seven. Haemoglobin moved far less: a one point five gram per litre difference, as you would expect in athletes who were not anaemic.",
      "on_screen": "Two bars, ferritin change: +18.4 vs +2.1 ug/L. Caption: difference 16.3 ug/L (95% CI 12.9-19.7). Smaller bar pair for haemoglobin: difference 1.5 g/L (95% CI 0.2-2.8).",
      "claim_refs": ["SYN-C04:results:ferritin_iron", "SYN-C04:results:ferritin_placebo", "SYN-C04:results:ferritin_between_group", "SYN-C04:results:haemoglobin_between_group", "SYN-C04:discussion"]
    },
    {
      "beat": "Tolerability",
      "narration": "Gut side effects were real but modest: twenty-one of one hundred seven on iron, against nine of one hundred seven on placebo.",
      "on_screen": "Icon array: 21/107 iron arm versus 9/107 placebo arm reporting gastrointestinal adverse events.",
      "claim_refs": ["SYN-C04:abstract:adverse_events"]
    },
    {
      "beat": "What it does not tell you",
      "narration": "Bottom line for coaches: alternate-day sixty milligrams rebuilt iron stores over twelve weeks. But no performance outcome was measured, and this only speaks to athletes who started below that thirty microgram threshold.",
      "on_screen": "Two-line summary: Rebuilds ferritin over 12 weeks. Not tested: performance. Applies to ferritin <30 ug/L only.",
      "claim_refs": ["SYN-C04:conclusion", "SYN-C04:limitations"]
    }
  ]
}

